/**
 * Build a sandboxed srcdoc document for untrusted (already sanitized) HTML.
 *
 * Security model:
 * - iframe sandbox="allow-scripts" WITHOUT allow-same-origin → opaque origin
 * - Only this trusted bootstrap may run; author scripts were stripped earlier
 * - Parent ↔ iframe messages are typed and entry-scoped
 * - Scroll restore is done INSIDE the iframe (parent cannot scroll opaque origins)
 */

export const VIEWER_CHILD_SOURCE = "small-web-viewer";
export const VIEWER_PARENT_SOURCE = "small-web-parent";

function bootstrapScript(entryId: string): string {
  // entryId is generated by us (UUID); escape for safe JS string embedding.
  const safeId = JSON.stringify(entryId);
  return `
<script>
(function () {
  var ENTRY_ID = ${safeId};
  var restoring = false;

  function post(payload) {
    parent.postMessage(Object.assign({
      source: "${VIEWER_CHILD_SOURCE}",
      entryId: ENTRY_ID
    }, payload), "*");
  }

  function sendScroll() {
    if (restoring) return;
    var y = window.scrollY || document.documentElement.scrollTop || 0;
    post({ type: "scroll", scrollY: y });
  }

  document.addEventListener("click", function (event) {
    var node = event.target;
    while (node && node !== document) {
      if (node.nodeType === 1 && node.getAttribute) {
        var addr = node.getAttribute("data-sw-nav");
        if (addr) {
          event.preventDefault();
          post({ type: "navigate", address: addr });
          return;
        }
      }
      node = node.parentNode;
    }
  }, true);

  window.addEventListener("scroll", sendScroll, { passive: true });

  window.addEventListener("message", function (event) {
    // Only accept commands from the embedding parent window.
    if (event.source !== parent) return;
    var data = event.data;
    if (!data || data.source !== "${VIEWER_PARENT_SOURCE}") return;
    if (data.entryId !== ENTRY_ID) return;

    if (data.type === "restore-scroll") {
      var y = typeof data.scrollY === "number" ? data.scrollY : 0;
      restoring = true;
      window.scrollTo(0, y);
      // Suppress scroll feedback until layout settles.
      setTimeout(function () { restoring = false; }, 80);
      post({ type: "scroll-restored", scrollY: y });
      return;
    }

    if (data.type === "report-scroll") {
      var cur = window.scrollY || document.documentElement.scrollTop || 0;
      post({ type: "scroll", scrollY: cur });
    }
  });

  function announceReady() {
    post({ type: "ready" });
  }

  if (document.readyState === "complete") {
    announceReady();
  } else {
    window.addEventListener("load", announceReady);
  }
})();
</script>
`;
}

export function buildViewerSrcDoc(
  html: string,
  title: string,
  entryId: string,
): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${escapeHtml(title)}</title>
<style>
  :root { color-scheme: light; }
  html, body { margin: 0; padding: 0; }
  body {
    font-family: "IBM Plex Serif", "Source Serif 4", Georgia, serif;
    line-height: 1.65;
    color: #1c2430;
    background:
      radial-gradient(1200px 500px at 10% -10%, #eef3f1 0%, transparent 55%),
      linear-gradient(180deg, #f7f8f6 0%, #eef1ef 100%);
    padding: 28px 32px 64px;
  }
  h1,h2,h3 { font-family: "Space Grotesk", "Avenir Next", sans-serif; letter-spacing: -0.02em; }
  a[data-sw-nav] { color: #1f6fbf; text-decoration-thickness: 1px; text-underline-offset: 3px; cursor: pointer; }
  a[aria-disabled="true"] { color: #7a8894; text-decoration: none; cursor: default; }
  p { max-width: 62ch; }
</style>
</head>
<body>
${html}
${bootstrapScript(entryId)}
</body>
</html>`;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
